K(y,A,B)[x:=N]=
\begin{cases}
K(y,A[x:=N],B),&y=x,\\
K(y,A[x:=N],B[x:=N]),&y\ne x,\ y\notin\operatorname{FV}_{pCIC}(N),\\
K(z,A[x:=N],(B[y:=\operatorname{var}(z)])[x:=N]),&y\ne x,\ y\in\operatorname{FV}_{pCIC}(N),
\end{cases}

C_0[x:=N]=
\begin{cases}
\operatorname{cofix}(f,A[x:=N],M),&x=f,\\
\operatorname{cofix}(f,A[x:=N],M[x:=N]),&x\ne f\land f\notin FV(N),\\
\operatorname{cofix}(f',A[x:=N],(M[f:=\operatorname{var}(f')])[x:=N]),&x\ne f\land f\in FV(N),
\end{cases}
